# The runtime module behind __init__.pyi: the stub's class has no docstring,
# this one does, and a class's docstring prefers it (as pyrefly's hover does).
class Widget:
    """A widget, documented in the runtime module."""

    size: int
    label: str

    def render(self) -> str:
        return self.label


class Opaque:
    def __init__(self, scope: dict) -> None:
        self.scope = scope

    def __call__(self, x: int) -> None:
        pass
